-- =============================================================================
-- THE STANDARD — v4 schema (additive only: no table, column or row is removed)
--
-- * Recurring tasks: task_series + one task row per occurrence date (unique),
--   generated by the planner and back-filled after inactivity.
-- * Events keep the time zone they were planned in.
-- * daily_scores: each day's score stored with its scoring-policy version.
-- * record_revisions: modification history for core records (trigger-written).
-- * Retrospective confirmations: when a completion was reported vs. happened.
-- * Fitness: exercises, sets, body metrics.
-- * Reliability: job_runs, Google sync outbox, Coach request idempotency,
--   atomic confirmation states.
-- =============================================================================

-- ---------------------------------------------------------------------------
-- Recurring tasks
-- ---------------------------------------------------------------------------
create table if not exists public.task_series (
  id               uuid primary key default gen_random_uuid(),
  user_id          uuid not null references auth.users(id) on delete cascade,
  goal_id          uuid references public.goals(id) on delete set null,
  title            text not null check (length(title) between 1 and 200),
  notes            text,
  recurrence       text not null check (recurrence in ('daily','weekdays','weekly','monthly')),
  weekdays         smallint[] not null default '{}',     -- for weekly: 0 = Sunday … 6 = Saturday
  due_time         time,                                 -- local wall-clock time in `timezone`
  timezone         text not null,                        -- IANA zone the series is planned in
  starts_on        date not null,
  ends_on          date,
  priority         smallint not null default 2 check (priority between 1 and 3),
  is_top_priority  boolean not null default false,
  active           boolean not null default true,
  last_generated_on date,
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now()
);
create index if not exists task_series_user_idx on public.task_series(user_id, active);
create trigger task_series_updated before update on public.task_series
  for each row execute function public.set_updated_at();

alter table public.tasks
  add column if not exists series_id       uuid references public.task_series(id) on delete set null,
  add column if not exists occurrence_date date,
  add column if not exists started_at      timestamptz,
  add column if not exists confirmed_at    timestamptz,
  add column if not exists retrospective   boolean not null default false;
alter table public.tasks drop constraint if exists tasks_series_occurrence_key;
alter table public.tasks add constraint tasks_series_occurrence_key unique (series_id, occurrence_date);

-- ---------------------------------------------------------------------------
-- Time zones and retrospective confirmations
-- ---------------------------------------------------------------------------
alter table public.events add column if not exists timezone text;
alter table public.commitments
  add column if not exists confirmed_at  timestamptz,
  add column if not exists retrospective boolean not null default false;
alter table public.activity_occurrences
  add column if not exists confirmed_at  timestamptz,
  add column if not exists retrospective boolean not null default false;
alter table public.habit_logs
  add column if not exists confirmed_at  timestamptz default now(),
  add column if not exists retrospective boolean not null default false;
alter table public.prayer_confirmations
  add column if not exists retrospective boolean not null default false;
alter table public.user_preferences
  add column if not exists last_reconciled_on date,
  add column if not exists weight_unit text not null default 'lb' check (weight_unit in ('lb','kg'));

-- ---------------------------------------------------------------------------
-- Daily score snapshots (history is never silently recalculated)
-- ---------------------------------------------------------------------------
create table if not exists public.daily_scores (
  user_id        uuid not null references auth.users(id) on delete cascade,
  score_date     date not null,
  policy_version text not null,
  integrity      jsonb not null,            -- daily integrity result as shown that day
  evolution      jsonb not null,            -- 7-day scoring report summary ending that day
  insight        jsonb,                     -- recommendation shown for that day, if any
  final          boolean not null default false,  -- true once the day has ended
  computed_at    timestamptz not null default now(),
  primary key (user_id, score_date, policy_version)
);

-- ---------------------------------------------------------------------------
-- Modification history
-- ---------------------------------------------------------------------------
create table if not exists public.record_revisions (
  id          uuid primary key default gen_random_uuid(),
  user_id     uuid not null references auth.users(id) on delete cascade,
  table_name  text not null,
  record_id   uuid not null,
  op          text not null check (op in ('insert','update','delete')),
  before      jsonb,          -- previous values of the columns that changed
  after       jsonb,          -- new values of the columns that changed
  actor       text not null,  -- user id, or 'system' for scheduled jobs
  created_at  timestamptz not null default now()
);
create index if not exists record_revisions_record_idx on public.record_revisions(record_id, created_at desc);
create index if not exists record_revisions_user_idx on public.record_revisions(user_id, created_at desc);

create or replace function public.log_revision()
returns trigger language plpgsql security definer set search_path = public as $$
declare
  o jsonb := case when tg_op = 'INSERT' then '{}'::jsonb else to_jsonb(old) end;
  n jsonb := case when tg_op = 'DELETE' then '{}'::jsonb else to_jsonb(new) end;
  b jsonb := '{}'::jsonb;
  a jsonb := '{}'::jsonb;
  k text;
begin
  for k in select jsonb_object_keys(o || n) loop
    if k in ('updated_at', 'search') then continue; end if;
    if (o -> k) is distinct from (n -> k) then
      if tg_op <> 'INSERT' then b := b || jsonb_build_object(k, o -> k); end if;
      if tg_op <> 'DELETE' then a := a || jsonb_build_object(k, n -> k); end if;
    end if;
  end loop;
  if tg_op = 'UPDATE' and b = '{}'::jsonb then return new; end if;
  -- Account deletion cascades: nothing to keep history for.
  if tg_op = 'DELETE' and not exists (select 1 from auth.users u where u.id = (o ->> 'user_id')::uuid) then return old; end if;
  insert into record_revisions(user_id, table_name, record_id, op, before, after, actor)
  values (coalesce((n ->> 'user_id')::uuid, (o ->> 'user_id')::uuid), tg_table_name,
          coalesce((n ->> 'id')::uuid, (o ->> 'id')::uuid), lower(tg_op),
          case when tg_op = 'INSERT' then null else b end, case when tg_op = 'DELETE' then null else a end,
          coalesce(auth.uid()::text, 'system'));
  return coalesce(new, old);
end $$;

do $$
declare t text;
begin
  foreach t in array array['tasks','commitments','activity_occurrences','events','workout_logs','prayer_confirmations','habit_logs'] loop
    execute format('drop trigger if exists %I on public.%I', t || '_revisions', t);
    execute format('create trigger %I after insert or update or delete on public.%I for each row execute function public.log_revision()', t || '_revisions', t);
  end loop;
end $$;

-- ---------------------------------------------------------------------------
-- Fitness
-- ---------------------------------------------------------------------------
create table if not exists public.workout_exercises (
  id              uuid primary key default gen_random_uuid(),
  user_id         uuid not null references auth.users(id) on delete cascade,
  workout_log_id  uuid not null references public.workout_logs(id) on delete cascade,
  name            text not null check (length(name) between 1 and 120),
  position        smallint not null default 0,
  notes           text,
  created_at      timestamptz not null default now()
);
create index if not exists workout_exercises_log_idx on public.workout_exercises(workout_log_id);

create table if not exists public.workout_sets (
  id               uuid primary key default gen_random_uuid(),
  user_id          uuid not null references auth.users(id) on delete cascade,
  exercise_id      uuid not null references public.workout_exercises(id) on delete cascade,
  set_number       smallint not null,
  reps             smallint check (reps between 0 and 1000),
  weight           numeric(7,2) check (weight >= 0),
  unit             text not null default 'lb' check (unit in ('lb','kg')),
  duration_seconds integer check (duration_seconds between 0 and 86400),
  distance_m       numeric(9,1) check (distance_m >= 0),
  rpe              numeric(3,1) check (rpe between 1 and 10),
  created_at       timestamptz not null default now()
);
create index if not exists workout_sets_ex_idx on public.workout_sets(exercise_id);

create table if not exists public.body_metrics (
  id            uuid primary key default gen_random_uuid(),
  user_id       uuid not null references auth.users(id) on delete cascade,
  measured_on   date not null,
  weight        numeric(6,2) check (weight > 0),
  unit          text not null default 'lb' check (unit in ('lb','kg')),
  body_fat_pct  numeric(4,1) check (body_fat_pct between 1 and 70),
  sleep_hours   numeric(4,1) check (sleep_hours between 0 and 24),
  source        text not null default 'manual' check (source in ('manual','imported')),
  note          text,
  created_at    timestamptz not null default now()
);
create index if not exists body_metrics_user_date_idx on public.body_metrics(user_id, measured_on);

-- ---------------------------------------------------------------------------
-- Reliability
-- ---------------------------------------------------------------------------
create table if not exists public.job_runs (
  id           uuid primary key default gen_random_uuid(),
  job          text not null,
  started_at   timestamptz not null default now(),
  finished_at  timestamptz,
  ok           boolean,
  summary      jsonb,
  error        text
);
create index if not exists job_runs_job_idx on public.job_runs(job, started_at desc);

create table if not exists public.sync_outbox (
  id              uuid primary key default gen_random_uuid(),
  user_id         uuid not null references auth.users(id) on delete cascade,
  event_id        uuid,
  op              text not null check (op in ('upsert','delete')),
  external_id     text,
  status          text not null default 'pending' check (status in ('pending','done','dead')),
  attempts        smallint not null default 0,
  next_attempt_at timestamptz not null default now(),
  last_error      text,
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now()
);
create index if not exists sync_outbox_due_idx on public.sync_outbox(next_attempt_at) where status = 'pending';

create table if not exists public.ai_requests (
  request_id  text primary key,
  user_id     uuid not null references auth.users(id) on delete cascade,
  response    jsonb,
  created_at  timestamptz not null default now()
);

-- Atomic confirmation workflow states
alter table public.ai_tool_executions drop constraint if exists ai_tool_executions_status_check;
alter table public.ai_tool_executions add constraint ai_tool_executions_status_check
  check (status in ('awaiting_confirmation','executing','executed','failed','rejected','undoing','undone','expired'));

-- ---------------------------------------------------------------------------
-- RLS
-- ---------------------------------------------------------------------------
do $$
declare t text;
begin
  foreach t in array array['task_series','workout_exercises','workout_sets','body_metrics'] loop
    execute format('alter table public.%I enable row level security', t);
    execute format('create policy "own rows select" on public.%I for select using (user_id = auth.uid())', t);
    execute format('create policy "own rows insert" on public.%I for insert with check (user_id = auth.uid())', t);
    execute format('create policy "own rows update" on public.%I for update using (user_id = auth.uid()) with check (user_id = auth.uid())', t);
    execute format('create policy "own rows delete" on public.%I for delete using (user_id = auth.uid())', t);
  end loop;
end $$;

-- Server-written history and snapshots: users can read and delete their own (privacy), not forge them.
alter table public.daily_scores enable row level security;
create policy "own scores select" on public.daily_scores for select using (user_id = auth.uid());
create policy "own scores delete" on public.daily_scores for delete using (user_id = auth.uid());
alter table public.record_revisions enable row level security;
create policy "own revisions select" on public.record_revisions for select using (user_id = auth.uid());
create policy "own revisions delete" on public.record_revisions for delete using (user_id = auth.uid());
alter table public.sync_outbox enable row level security;
create policy "own outbox select" on public.sync_outbox for select using (user_id = auth.uid());
alter table public.ai_requests enable row level security;
create policy "own ai requests select" on public.ai_requests for select using (user_id = auth.uid());
-- job_runs: service role only (RLS on, no policies).
alter table public.job_runs enable row level security;

-- Retention for operational tables
create or replace function public.apply_retention_v4()
returns jsonb language plpgsql security definer set search_path = public as $$
declare n1 int; n2 int; n3 int;
begin
  delete from job_runs where started_at < now() - interval '30 days'; get diagnostics n1 = row_count;
  delete from sync_outbox where status = 'done' and updated_at < now() - interval '30 days'; get diagnostics n2 = row_count;
  delete from ai_requests where created_at < now() - interval '7 days'; get diagnostics n3 = row_count;
  return jsonb_build_object('job_runs', n1, 'outbox', n2, 'ai_requests', n3);
end $$;
revoke all on function public.apply_retention_v4() from public, anon, authenticated;
grant execute on function public.apply_retention_v4() to service_role;
